def largest_rectangle_area(heights):
    stack = []                                                              # holds indices of an increasing sequence of bar heights
    max_area = 0
    for i in range(len(heights) + 1):
        h = 0 if i == len(heights) else heights[i]
        while stack and heights[stack[-1]] >= h:
            height = heights[stack.pop()]
            width = i if not stack else i - stack[-1] - 1                  # width spans from just after the new stack top to the current position
            max_area = max(max_area, height * width)
        stack.append(i)
    return max_area

def maximal_rectangle(matrix):
    if not matrix:
        return 0
    cols = len(matrix[0])
    heights = [0] * cols
    max_area = 0
    for row in matrix:
        for j in range(cols):
            heights[j] = heights[j] + 1 if row[j] == '1' else 0            # extend the running height, or reset to 0 on a '0'
        max_area = max(max_area, largest_rectangle_area(heights))          # reuse the histogram solution for this row's heights
    return max_area


